import { useIntl } from 'react-intl';

import { BasicContainer, NoDataYet } from 'components';

import { StyledEmptyStateContainer } from './CommercialResultsEmptyState.styles';

interface CommercialResultsEmptyStateProps {
  dataTestId?: string;
}

export const CommercialResultsEmptyState: React.FC<
  CommercialResultsEmptyStateProps
> = ({ dataTestId = 'commercial-results-empty-state' }) => {
  const { formatMessage } = useIntl();

  return (
    <BasicContainer fullWidth={true} data-testid={dataTestId}>
      <StyledEmptyStateContainer>
        <NoDataYet
          description={formatMessage({
            id: 'ValueCreation.CommercialResults.emptyState.description',
          })}
          illustration="noDataAvailable"
          size="auto"
          fontSize="large"
        />
      </StyledEmptyStateContainer>
    </BasicContainer>
  );
};
